import sys

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    offers = []
    for i in range(1, m + 1):
        l, r = map(int, lines[i].split())
        offers.append((l, r))

    results = []

    for x in range(1, n + 1):
        occupied = [False] * (n + 2)  # 1-indexed, extra buffer
        days_count = 0

        for l, r in offers:
            length = r - l + 1
            if length < x:
                continue

            # Check if all days in [l, r] are free
            can_accept = True
            for day in range(l, r + 1):
                if occupied[day]:
                    can_accept = False
                    break

            if can_accept:
                for day in range(l, r + 1):
                    occupied[day] = True
                days_count += length

        results.append(str(days_count))

    return '\n'.join(results) + '\n'

if __name__ == "__main__":
    print(solution(sys.stdin.read()))

