def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    num_nodes = 2 * m
    adj = [[] for _ in range(num_nodes)]
    rev_adj = [[] for _ in range(num_nodes)]

    def literal_to_node(var, is_negated):
        # var ranges from 1 to m
        # Return node index for the literal (positive vs negated)
        idx = (var - 1) * 2
        if is_negated:
            return idx + 1
        return idx

    def negation_node(node):
        # Flip between positive and negative node for same variable
        return node ^ 1

    for i in range(1, n + 1):
        parts = list(map(int, lines[i].split()))
        k = parts[0]
        literals = parts[1:]

        nodes = [literal_to_node(abs(lit), lit < 0) for lit in literals]

        if len(nodes) == 1:
            # Single literal clause: must be true
            node = nodes[0]
            # No self-implications needed, but it forces this literal to true
            # This will be handled during assignment
        else:
            # For each pair of literals in the clause
            for j in range(len(nodes)):
                for p in range(j + 1, len(nodes)):
                    node1, node2 = nodes[j], nodes[p]
                    # Add implications: ¬l1 → l2 and ¬l2 → l1
                    adj[negation_node(node1)].append(node2)
                    rev_adj[node2].append(negation_node(node1))

                    adj[negation_node(node2)].append(node1)
                    rev_adj[node1].append(negation_node(node2))

    # Kosaraju's algorithm to find SCCs
    visited = [False] * num_nodes
    finish_stack = []

    def dfs1(u):
        visited[u] = True
        for v in adj[u]:
            if not visited[v]:
                dfs1(v)
        finish_stack.append(u)

    for u in range(num_nodes):
        if not visited[u]:
            dfs1(u)

    visited = [False] * num_nodes
    component = [-1] * num_nodes
    component_order = []
    comp_num = 0

    def dfs2(u):
        visited[u] = True
        component[u] = comp_num
        for v in rev_adj[u]:
            if not visited[v]:
                dfs2(v)

    while finish_stack:
        u = finish_stack.pop()
        if not visited[u]:
            comp_num += 1
            dfs2(u)
            component_order.append(comp_num - 1)  # store component ID

    # Check if any variable and its negation are in the same component
    for var in range(m):
        pos_node = var * 2
        neg_node = var * 2 + 1
        if component[pos_node] == component[neg_node]:
            return "NO"

    # Construct assignment
    assignment = [''] * m
    for var in range(m):
        # Assign based on component order: TRUE if positive literal's component > neg literal's component
        pos_comp = component[var * 2]
        neg_comp = component[var * 2 + 1]
        if pos_comp > neg_comp:
            assignment[var] = '1'
        else:
            assignment[var] = '0'

    return "YES\n" + "".join(assignment)

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    MOD = 1000000007

    # Find missing positions
    missing_positions = []
    for i in range(n):
        if a[i] == -1:
            missing_positions.append(i)

    k = len(missing_positions)

    # Find used and missing numbers
    used = set()
    for val in a:
        if val != -1:
            used.add(val)

    missing_numbers = [num for num in range(1, n + 1) if num not in used]

    # Count how many missing positions have ((position + 1) in missing_numbers)
    x = 0
    for pos in missing_positions:
        target = pos + 1
        if target in missing_numbers:
            x += 1

    # Use inclusion-exclusion principle
    # Answer = sum_{m=0}^{x} (-1)^m * C(x, m) * (k-m)!

    # Precompute factorials
    fact = [1] * (k + 1)
    for i in range(1, k + 1):
        fact[i] = (fact[i - 1] * i) % MOD

    def nCr_mod(n, r):
        if r > n or r < 0:
            return 0
        num = fact[n]
        den_inv = pow(fact[r], MOD - 2, MOD)
        den_inv_inv = pow(fact[n - r], MOD - 2, MOD)
        return (num * pow(den_inv * den_inv_inv % MOD, MOD - 2, MOD)) % MOD

    def nCr(n, r):
        if r > n or r < 0:
            return 0
        numerator = 1
        denominator = 1
        for i in range(min(r, n - r) + 1):
            numerator = (numerator * (n - i)) % MOD
            denominator = (denominator * (i + 1)) % MOD
        return (numerator * pow(denominator, MOD - 2, MOD)) % MOD

    ans = 0
    for m in range(x + 1):
        term = (nCr(x, m) * fact[k - m]) % MOD
        if m % 2 == 0:
            ans = (ans + term) % MOD
        else:
            ans = (ans - term + MOD) % MOD

    return str(ans)


