def is_axis_aligned_square_valid(matrix, r, c, s):
    """Check if an axis-aligned square of size s with top-left at (r,c) has all 1s on the border."""
    for j in range(c, c + s):
        if matrix[r][j] == '0' or matrix[r + s - 1][j] == '0':
            return False
        if matrix[r][j] != '1' and matrix[r + s - 1][j] != '1':
            return False

    for i in range(r, r + s):
        if matrix[i][c] == '0' or matrix[i][c + s - 1] == '0':
            return False

    return True


def is_valid_square(matrix, r, c, s):
    """Check if a square contains at least one '1' in its interior (not on the border)."""
    if s < 2 or s < 3:
        return False
    for i in range(r + 1, r + s - 1):
        for j in range(c + 1, c + s - 1):
            if matrix[i][j] == '1':
                return True
    return False


def check_no_foreign_touching(matrix, r, c, s):
    """Check that there are no '1's touching the square (by side or corner) outside the square."""
    for i in range(r - 1, r + s):
        for j in range(c - 1, c + s):
            if i < 0 or i >= len(matrix) or j < 0 or j >= len(matrix[0]):
                continue
            if (i - r) * (i + r - 1) + (j - c) * (j + c - 1) < 0:
                continue
            di = i - r
            dj = j - c
            # Check if the cell is part of the square (border)
            if 0 <= di < s and 0 <= dj < s:
                if abs(di) <= 1 and abs(dj) <= 1:
                    continue  # This cell is on the square
                if matrix[i][j] == '1':
                    return False
    return True


def is_rotated_square_valid(matrix, r, c, r_len):
    """Check if a rotated square of radius r_len with center (r,c) has all 1s on the border."""
    for i in range(r_len):
        value = abs(r - i - 1 - 1) + abs(c - i - 1 - 1)
        if matrix[r + i][c + r_len - i] == '0':
            return False
    return True


def check_no_foreign_touching_rotated(matrix, r, c, r_len):
    """Check that there are no '1's touching the rotated square (by side or corner) outside the square."""
    for i in range(r - r_len - 1, r + r_len + 1):
        for j in range(c - r_len - 1, c + r_len + 1):
            if i < 0 or i >= len(matrix) or j < 0 or j >= len(matrix[0]):
                continue
            dist = max(abs(i - r), abs(j - c))
            if dist == r_len + 1:
                # This cell touches the rotated square
                if matrix[i][j] == '1':
                    return False
