    parent = [0] * (n + 1)
    children = [[] for _ in range(n + 1)]
    visited = [False] * (n + 1)
    queue = [1]
    visited[1] = True

    bfs_order = []
    while queue:
        u = queue.pop(0)
        bfs_order.append(u)
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                parent[v] = u
                children[u].append(v)
                queue.append(v)

    bfs_order.reverse()

    # Precompute subtree sizes
    subtree_size = [0] * (n + 1)
    for u in bfs_order:
        subtree_size[u] = 1
        for v in children[u]:
            subtree_size[u] += subtree_size[v]

    # Edge index map for output
    edge_idx = {}
    for idx, (u, v) in enumerate(edges):
        edge_idx[(min(u, v), max(u, v))] = idx + 1

    @lru_cache(None)
    def dp(u, s):
        """
        Returns (min_cut_edges, cost) for subtree at u with component size s (U is in component).
        """
        if s == 1:
            return (0, set())  # No edges cut

        if subtree_size[u] < s:
            return (0, set())

        if not children[u]:
            return (float('inf'), set())

        # Generate all combinations of child subtree sizes that sum to s-1
        best_cost = float('inf')
        best_cut_edges = set()

        child_subtrees = [(v, subtree_size[v]) for v in children[u]]

        # DFS to generate combinations
        def generate(idx, remaining_s, cut_edges, current_cost):
            nonlocal best_cost, best_cut_edges

            if remaining_s == 0:
                if current_cost < best_cost or (current_cost == best_cost and cut_edges < best_cut_edges if best_cut_edges is not None else True):
                    best_cost = current_cost
                    best_cut_edges = cut_edges.copy()
                return

            if remaining_s < 0 or idx >= len(child_subtrees):
                return

            v, max_sz = child_subtries[idx]

            # Option 1: Cut edge to v
            new_cut = set(cut_edges)
            new_cut.add(edge_idx[(u, v)])

            # Try all possible sizes from v's subtree
            for sz in range(1, min(remaining_s + 1, max_sz + 1)):
                cost, _ = dp(v, sz)
                generate(idx + 1, remaining_s - sz, new_cut, current_cost + cost + 1)  # +1 for cut edge

            # Option 2: Don't cut edge (include v in component)
            for sz in range(1, min(remaining_s + 1, max_sz + 1)):
                cost, kids_cut = dp(v, sz)
                generate(idx + 1, remaining_s - sz, kids_cut.copy(), current_cost + cost)

        generate(0, s - 1, set(), 0)

        return (best_cost, best_cut_edges) if best_cost != float('inf') else (0, set())

    result = (float('inf'), set())
    final_set = None

    for u in range(1, n + 1):
