    # Build suffix array
    sa = sorted(range(n), key=lambda i: s[i:])
    rank = [0] * n
    for i in range(n):
        rank[sa[i]] = i

    # Build LCP array
    lcp = [0] * n
    k = 0
    for i in range(n):
        if rank[i] == 0:
            k = 0
            continue
        j = sa[rank[i] - 1]
        while i + k < n and j + k < n and s[i+k] == s[j+k]:
            k += 1
        lcp[rank[i]] = k
        if k > 0:
            k -= 1

    def get_lcp(i, j):
        """Get LCP length between suffix starting at i and suffix starting at j"""
        if rank[i] > rank[j]:
            i, j = j, i
        return lcp[rank[j]]

    def find_best_extension(start_position):
        """Find the maximum length journey starting a substring at start_position"""
        max_journey_from_here = 1

        # Try different end positions for first string t1
        for end in range(start_position + 1, n + 1):
            len1 = end - start_position

            # Last position of t1
            last_pos = start_position + len1 - 1

            if last_pos >= n - 1:
                break

            # Find max LCP between t1 and any suffix starting after last_pos
            best_match = 0
            for next_start in range(last_pos + 1, n - len1 + 1):
                if best_match >= len1 - 1:
                    break
                lcp_val = get_lcp(start_position, next_start)
                if lcp_val > best_match:
                    best_match = lcp_val

            # If we found a matching substring that's strictly shorter
            if best_match < len1 and best_match > 0:
                # Continue building journey (greedy approach)
                curr_length = 1

                while True:
                    previous_start = start_position
                    previous_len = len1

                    last_end = start_position + len1 - 1

                    # Find next substring
                    next_start = -1
                    next_len = 0

                    for cand_start in range(last_end + 1, n):
                        if next_len >= previous_len - 1:
                            break

                        # Check if we can extend
                        common = get_lcp(start_position, cand_start)
                        if common > next_len and common < previous_len:
                            next_start = cand_start
                            next_len = common
                            curr_length += 1

                    if next_len < previous_len and next_len > 0:
                        len1 = next_len
                        start_position = next_start
                    else:
                        break

                if curr_length > max_journey_from_here:
                    max_journey_from_here = curr_length

            if best_match >= len1 - 1:
                break

        return max_journey_from_here

    # Try each starting position
    max_journey = 0
    for start in range(n):
        j = find_best_extension(start)
        if j > max_journey:
            max_journey = j

    if max_journey == 0:
