def solution(s):
    lines = s.strip().split('\n')
    idx = 0

    if idx >= len(lines):
        return ""

    t = int(lines[idx])
    idx += 1

    results = []

    for _ in range(t):
        # Skip empty line if present
        while idx < len(lines) and lines[idx].strip() == '':
            idx += 1

        if idx >= len(lines):
            break

        n = int(lines[idx])
        idx += 1

        tree = []
        for i in range(n):
            parts = list(map(int, lines[idx].split()))
            idx += 1

            if parts[0] == -1:
                # Internal node
                tree.append((parts[1], parts[2]))
            else:
                # Leaf node
                tree.append(('leaf', parts[0]))

        # Count leaves in subtree
        @lru_cache(maxsize=None)
        def count_leaves(node):
            if tree[node][0] == 'leaf':
                return 1
            return count_leaves(tree[node][0]) + count_leaves(tree[node][1])

        total_leaves = count_leaves(0)
        total_ops = total_leaves - 1  # Total operations to reduce to 1

        @lru_cache(maxsize=None)
        def solve(node):
            if tree[node][0] == 'leaf':
                return tree[node][1]

            left_val = solve(tree[node][0])
            right_val = solve(tree[node][1])

            left_leaves = count_leaves(tree[node][0])
            right_leaves = count_leaves(tree[node][1])

            # Operations in this subtree
            subtree_ops = left_leaves + right_leaves - 1

            # Operations from this node down to the root in the entire tree
            # = total_ops - (ops before reaching this node)
            # Ops before reaching = (1 - left_leaves) + (1 - right_leaves)
            # Actually, we think differently: if this node is the k-th operation
            # from the bottom, what player moves here?

            # Operation number from bottom (1-indexed): k = subtree_ops
            # If k <= total_ops and (total_ops - k + 1) is odd: Pieguy's turn
            # If (total_ops - k + 1) is even: Piegirl's turn

            op_num = subtree_ops
            # Number of moves after this operation in the entire game
            moves_after = total_ops - op_num

            if (moves_after % 2 == 0):  # Pieguy gets this operation
                return max(left_val, right_val)
            else:  # Piegirl gets this operation
                return min(left_val, right_val)

        result = solve(0)
        results.append(str(result))

    return '\n'.join(results)


