    elif n == 2:
        return str((r - l + 1) * (r - l)) + '\n'

    # For n >= 3
    # If n is too large, 2^(n-1) > r, so no valid progressions exist
    if (1 << (n - 1)) > r:
        return "0\n"

    import math

    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    count = 0
    # q^(n-1) <= r, so q <= r^(1/(n-1))
    max_q = int(r ** (1.0 / (n - 1))) + 2

    for q in range(1, max_q):
        denom = q ** (n - 1)
        if denom > r:
            break
        for p in range(q + 1, max_q):
            num = p ** (n - 1)
            if num > r:
                break
            if gcd(p, q) != 1:
                continue

            # Valid k satisfies: k*denom >= l AND k*num <= r
            start_k = (l + denom - 1) // denom if denom != 0 else 1
            end_k = r // num
            if start_k <= end_k:
                count += (end_k - start_k + 1)

    # Multiply by 2 for both increasing (p > q) and decreasing (p < q) progressions
    return str(count * 2) + '\n'


