def calc_score(combo):
    score = 0
    m = len(combo)
    for i in range(m):
        for j in range(i + 1, m):
            x1, y1 = combo[i]
            x2, y2 = combo[j]
            dx = x1 - x2
            dy = y1 - y2
            score += dx * dx + dy * dy
    return score


