    for i in range(s, n):
        a_list.append((101 * a_list[-1] + 10007) % MOD)
    a = a_list

    # GCD function
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    # Popcount: number of set bits
    def popcount(x):
        c = 0
        while x:
            c += 1
            x &= x - 1
        return c

    # Build transition matrix M where M[i][j] = bridges from island i+1 to island j+1
    def build_M():
        M = [[0] * n for _ in range(n)]
        for i in range(n):
            M[i][i] = 1  # Stay option
            for j in range(n):
                if i != j:
                    u, v = i + 1, j + 1
                    g = gcd(u, v)
                    M[i][j] = 1 << popcount(g)
        return M

    # Matrix multiplication mod MOD
    def mat_mul(A, B):
        result = [[0] * n for _ in range(n)]
        for i in range(n):
            for k in range(n):
                if A[i][k]:
                    for j in range(n):
                        result[i][j] = (result[i][j] + A[i][k] * B[k][j]) % MOD
        return result

    # Matrix exponentiation
    def mat_pow(A, p):
        if p == 0:
            return [[0] * n for _ in range(n)]

        result = [[0] * n for _ in range(n)]
        for i in range(n):
            result[i][i] = 1

        base = [row[:] for row in A]
        while p > 0:
            if p & 1:
                result = mat_mul(result, base)
            base = mat_mul(base, base)
            p >>= 1
        return result

    # Handle t = 0 case
    if t == 0:
        return "0\n"

    # Build and exponentiate transition matrix
    M = build_M()
    M_t = mat_pow(M, t)

    # Compute answer[i] = number of ways to reach island i+1 after t days
    # From home, we go to island j with a[j] ways
    # Then from j to i in M_t[j][i] ways
    ans = [0] * n
    for i in range(n):
        for j in range(n):
            ans[i] = (ans[i] + M_t[j][i] * a[j]) % MOD

    # XOR sum of all answers
    xor_sum = 0
    for ans_val in ans:
        xor_sum ^= ans_val

    return str(xor_sum % MOD) + '\n'


