        mat = [[0] * size for _ in range(size)]
        for i in range(size):
            for p in unique_petals:
                if i + p < size:
                    mat[i][i + p] = (mat[i][i + p] + petal_counts[p]) % MOD

        trans_mat = mat_pow(mat, N, size, MOD)
        dp_bouquet_final = [trans_mat[0][k] for k in range(size)]
    else:
        # For small N, use direct DP
        for _ in range(N):
            new_dp = [0] * (max_petal + 1)
            for i in range(max_petal + 1):
                if dp_bouquet[i]:
                    for p in unique_petals:
                        if i + p < len(new_dp):
                            new_dp[i + p] = (new_dp[i + p] + dp_bouquet[i] * petal_counts[p]) % MOD
            dp_bouquet = new_dp

    # Compute basket DP
    # Build unique box count map
    box_counts = defaultdict(int)
    for b in boxes:
        box_counts[b] += 1

    max_box = sum(box_counts.keys()) if box_counts else 0
    dp_basket = [0] * (max_box + 1)
    dp_basket[0] = 1

    # For basket (any number of boxes, ordered sequences)
    for b in sorted(box_counts.keys(), reverse=True):
        for i in range(b, len(dp_basket)):
            dp_basket[i] = (dp_basket[i] + dp_basket[i - b] * box_counts[b]) % MOD

    # Result: sum of product of matching basin/basket totals
    result = 0
    min_len = min(len(dp_bouquet_final), len(dp_basket))
    for k in range(min_len):
        result = (result + dp_bouquet_final[k] * dp_basket[k]) % MOD

    return f"{result}\n"

