import sys
from collections import deque

def solution(s):
    """
    Solve the magic number problem using BFS.
    Find the minimum number of subtractions to reduce the number to zero,
    where each subtraction must be a digit present in the current number.
    """
    try:
        n = int(s.strip())
    except:
        return "0\n"

    if n <= 0:
        return "0\n"

    # BFS to find minimum operations
    # visited stores number -> steps to reach it
    visited = {n: 0}
    queue = deque([n])

    while queue:
        curr = queue.popleft()
        if curr == 0:
            return str(visited[curr]) + '\n'

        # Get all distinct digits in current number
        digits = set(str(curr))
        steps = visited[curr]

        for d in digits:
            d_int = int(d)
            if d_int > 0:  # Can only subtract positive digits
                nxt = curr - d_int
                if nxt not in visited:
                    visited[nxt] = steps + 1
                    queue.append(nxt)

    return "0\n"


