def count_distinct_subsequences(arr):
    if not arr:
        return 1
    dp = [0] * len(arr)
    dp[0] = 2  # empty + [arr[0]]
    last = {}
    for i in range(len(arr)):
        v = arr[i]
        dp[i] = 2 * dp[i-1] if i > 0 else 2
        if v in last:
            dp[i] -= dp[last[v]-1]
        last[v] = i
    return dp[-1]

