    roads = []
    for i in range(1, m + 1):
        a, b = map(int, lines[i].split())
        roads.append((a - 1, b - 1))  # Convert to 0-indexed

    def crossing(p1, q1, p2, q2):
        """Check if two chords cross when placed on the same side."""
        # Normalize so p < q for each chord
        x1, y1 = sorted((p1, q1))
        x2, y2 = sorted((p2, q2))
        # They cross if endpoints are interleaved: p1 < p2 < q1 < q2
