                inner_ok = False
                break
        if inner_ok:
            assignments[idx] = 1
            if backtrack(idx + 1):
                return True

        # Try outside (0)
        outer_ok = True
        for j in range(idx):
            if assignments[j] == 0 and crossing(p1, q1, roads[j][0], roads[j][1]):
                outer_ok = False
                break
        if outer_ok:
            assignments[idx] = 0
            if backtrack(idx + 1):
                return True

        return False

    if backtrack(0):
        return ''.join('i' if x == 1 else 'o' for x in assignments) + '\n'
    else:
